import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"URI 协议（lertaro://）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/uri-protocol.md","filePath":"zh-CN/user-guide/uri-protocol.md","lastUpdated":1786513079000}'),r={name:"zh-CN/user-guide/uri-protocol.md"};function c(s,e,l,n,i,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="uri-协议-lertaro" tabindex="-1">URI 协议（lertaro://） <a class="header-anchor" href="#uri-协议-lertaro" aria-label="Permalink to &quot;URI 协议（lertaro://）&quot;">​</a></h1><p>Lertaro 会自动把自己注册为 <code>lertaro://</code> 链接的处理程序——不需要额外的安装步骤，第一次运行时就会自动完成注册。这样任何能打开链接的东西（浏览器、快捷方式、别的程序、脚本）都能直接跳到 Lertaro 的某个具体位置，而不是只能靠热键触发。</p><p>如果 Lertaro 还没运行，打开一个 <code>lertaro://</code> 链接会先启动它，再执行这个链接指向的操作。如果已经在运行，正在运行的那个实例会直接处理这个链接——不会再启动第二份进程。</p><h2 id="支持的链接" tabindex="-1">支持的链接 <a class="header-anchor" href="#支持的链接" aria-label="Permalink to &quot;支持的链接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>链接</th><th>作用</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>激活快速搜索窗口——效果和用热键呼出它一样。</td></tr><tr><td><code>lertaro://search/[关键词]</code></td><td>激活快速搜索窗口，并预填 <code>[关键词]</code>。</td></tr><tr><td><code>lertaro://fullsearch/[关键词]</code></td><td>打开完整搜索窗口，并预填 <code>[关键词]</code>。</td></tr><tr><td><code>lertaro://settings/page/[分区]</code></td><td>打开设置窗口，并切到指定的顶层分区。</td></tr><tr><td><code>lertaro://settings/entry/[序号]</code></td><td>打开设置窗口，并直接跳转到某一项具体设置，并高亮显示。</td></tr><tr><td><code>lertaro://localsend</code></td><td>打开空白的 LocalSend 发送窗口。</td></tr><tr><td><code>lertaro://localsend/items[/编码后的项目...]</code></td><td>切换到文件/文件夹模式，并可按路径段添加一个或多个项目。</td></tr><tr><td><code>lertaro://localsend/text[/编码后的文本]</code></td><td>切换到文本模式，并可填入编码后的文本。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>第一个会激活快速搜索窗口，并已经用&quot;report&quot;过滤好；第二个会直接打开设置窗口的&quot;外观&quot;页。</p><p><code>[分区]</code> 对应侧边栏顶层的某一项：<code>Service</code>、<code>Index</code>、<code>General</code>、<code>Appearance</code>、<code>Hotkeys</code>、 <code>Plugins</code>、<code>Favorites</code>、<code>History</code>、<code>QuickPanel</code>、<code>About</code>——不区分大小写。</p><p><code>[序号]</code> 不是给人手动输入用的——它是<a href="./instant-answers.html">设置搜索</a>在你选中某项设置结果时自己生成的一个数字，选中结果会自动带上这个序号，原样跳转回那一项设置。这个序号在重启之间并不稳定，不要指望某个具体数字每次都对应同一项设置。</p><h2 id="localsend-链接" tabindex="-1">LocalSend 链接 <a class="header-anchor" href="#localsend-链接" aria-label="Permalink to &quot;LocalSend 链接&quot;">​</a></h2><p>每个文件/文件夹路径或文本值都必须整体编码为一个 URL 路径段。添加多个项目时，为每个项目追加一个独立的编码路径段；所有路径都必须是已经存在的绝对路径。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Ca.txt/D%3A%5CShared</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20world</span></span></code></pre></div><p><code>lertaro://localsend/items</code> 会打开收集页并切到文件/文件夹模式，<code>lertaro://localsend/text</code> 则切到文本模式。带有内容的链接会继续进入设备选择，但绝不会自动选择设备或开始传输。如果发送窗口已经打开，这个链接不会执行任何操作，也不会改变窗口当前的内容或状态。如果 LocalSend 尚未启用，Lertaro 会改为打开 LocalSend 设置页。内容无效或过长时，整个请求都会被忽略。</p><h2 id="无法识别的链接" tabindex="-1">无法识别的链接 <a class="header-anchor" href="#无法识别的链接" aria-label="Permalink to &quot;无法识别的链接&quot;">​</a></h2><p>任何匹配不上已知路由的链接——打错了字、分区不存在、<code>lertaro://</code> 后面跟了一堆乱七八糟的内容——都会被直接忽略。由于任何网站或程序都能在你不知情的情况下调起这个协议，一个错误或异常的链接不应该产生任何出人意料的效果；这类情况只会记进日志方便你自己排查，除此之外什么都不会发生。</p>`,15)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
